() => {
  const result = {};
  result.bodyText = document.body.innerText.substring(0, 3000);
  result.timeMatches = document.body.innerText.match(/\b\d{1,2}[:.]\d{2}\b/g);
  return result;
}

() => {
  const result = {};
  result.bodyText = document.body.innerText.substring(0, 3000);
  return result;
}

() => {
  const text = document.body.innerText;
  return {
    hasKickOff: text.includes('Kick off'),
    hasKO: text.includes('KO'),
    fullLength: text.length,
    sample: text.substring(0, 2000)
  };
}

() => {
  const data = __data();
  if (data && data.length > 0) {
    return data.filter(d => JSON.stringify(d).includes('Hibernian') || JSON.stringify(d).includes('kick') || JSON.stringify(d).includes('time'));
  }
  return "no data";
}

() => {
  const elements = __find("\\d{1,2}:\\d{2}");
  return elements.map(function(e) {
    return {
      text: e.textContent.trim(),
      tag: e.tagName,
      index: e.getAttribute('data-testid') || ''
    };
  });
}

() => {
  // Get the full HTML to find time information
  const html = document.documentElement.outerHTML;
  const timeMatches = html.match(/\d{1,2}[:.]\d{2}/g);
  return {
    hasTime: html.includes('kick') || html.includes('Kick'),
    hasStartTime: html.includes('start time') || html.includes('Start Time'),
    times: timeMatches ? timeMatches.slice(0, 20) : []
  };
}

() => {
  const html = document.documentElement.outerHTML;
  const timeMatches = html.match(/\d{1,2}[:.]\d{2}/g);
  return JSON.stringify({
    hasKick: html.toLowerCase().includes('kick'),
    times: timeMatches ? [...new Set(timeMatches)].slice(0, 30) : []
  });
}

() => {
  const html = document.documentElement.outerHTML;
  const timeMatches = html.match(/\d{1,2}[:.]\d{2}/g);
  const result = {
    hasKick: html.toLowerCase().includes('kick'),
    times: timeMatches ? [...new Set(timeMatches)].slice(0, 30) : []
  };
  document.title = JSON.stringify(result);
  return result;
}
